for (size_t i = start; i < end; ++i) {
    Particle& p = particles[i];
    float density = selfDens;
    for (int dz = -1; dz <= 1; ++dz) {
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dx = -1; dx <= 1; ++dx) {
                int cellIndex = particleTable[(dz + 1) * 9 + (dy + 1) * 3 + (dx + 1)];
                if (cellIndex == -1) continue;
                for (size_t j = cellIndex; j < particleCount && particles[j].cellIndex == cellIndex; ++j) {
                    if (i == j) continue;
                    float3 diff = particles[j].position - p.position;
                    float r2 = diff.x * diff.x + diff.y * diff.y + diff.z * diff.z;
                    if (r2 >= h2) continue;
                    float r = std::sqrt(r2);
                    float w = poly6 * (h2 - r2) * (h2 - r2) * (h2 - r2);
                    density += mass * w;
                }
            }
        }
    }
    p.density = density;
    p.pressure = gasConstant * (density - restDensity);
}

